FILES["app/core/config.py"] = 'from functools import lru_cache\n\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\nfrom sqlalchemy.engine import URL\n\n\nclass Settings(BaseSettings):\n    app_name: str = "Secret Management Service"\n    app_env: str = "dev"\n    app_debug: bool = True\n    docs_enabled: bool = True\n\n    api_v1_prefix: str = "/api/v1"\n\n    postgres_host: str = "postgres"\n    postgres_port: int = 5432\n    postgres_db: str = "secret_manager"\n    postgres_user: str = "secret_manager"\n    postgres_password: str = "change_me"\n\n    jwt_secret_key: str = "change_me_generate_real_value"\n    jwt_algorithm: str = "HS256"\n    access_token_expire_minutes: int = 30\n    api_key_pepper: str = "change_me_generate_real_value"\n\n    log_level: str = "INFO"\n\n    master_key_file: str = "/run/secrets/sms_master_key"\n    encryption_key_version: str = "local-v1"\n\n    model_config = SettingsConfigDict(\n        env_file=".env",\n        env_file_encoding="utf-8",\n        extra="ignore",\n    )\n\n    @property\n    def database_url(self) -> str:\n        return URL.create(\n            drivername="postgresql+psycopg",\n            username=self.postgres_user,\n            password=self.postgres_password,\n            host=self.postgres_host,\n            port=self.postgres_port,\n            database=self.postgres_db,\n        ).render_as_string(hide_password=False)\n\n\n@lru_cache\ndef get_settings() -> Settings:\n    return Settings()\n\n\nsettings = get_settings()\n'

FILES["app/core/datetime.py"] = 'from datetime import UTC, datetime\n\n\ndef utc_now() -> datetime:\n    return datetime.now(UTC)\n\n\ndef ensure_aware_utc(value: datetime | None) -> datetime | None:\n    if value is None:\n        return None\n\n    if value.tzinfo is None or value.utcoffset() is None:\n        raise ValueError("datetime value must be timezone-aware")\n\n    return value.astimezone(UTC)\n'

FILES["app/core/audit_actions.py"] = 'class AuditAction:\n    AUTH_LOGIN = "auth.login"\n    AUTH_API_KEY = "auth.api_key"\n\n    SERVICE_ACCOUNT_CREATED = "service_account.created"\n\n    SECRET_CREATED = "secret.created"\n    SECRET_READ = "secret.read"\n    SECRET_ROTATED = "secret.rotated"\n    SECRET_DELETED = "secret.deleted"\n\n    POLICY_CREATED = "policy.created"\n\n\nclass AuditStatus:\n    SUCCESS = "success"\n    DENIED = "denied"\n    FAILED = "failed"\n'

FILES["scripts/generate_master_key.py"] = 'from pathlib import Path\n\nfrom cryptography.fernet import Fernet\n\n\nPROJECT_ROOT = Path(__file__).resolve().parents[1]\nSECRETS_DIR = PROJECT_ROOT / "secrets"\nMASTER_KEY_FILE = SECRETS_DIR / "sms_master_key"\n\n\ndef main() -> None:\n    SECRETS_DIR.mkdir(exist_ok=True)\n\n    if MASTER_KEY_FILE.exists():\n        raise FileExistsError(\n            f"Master key already exists: {MASTER_KEY_FILE}\n"\n            "Delete it manually only if you are sure old encrypted secrets are not needed."\n        )\n\n    MASTER_KEY_FILE.write_text(\n        Fernet.generate_key().decode("utf-8") + "\n",\n        encoding="utf-8",\n    )\n\n    print(f"Master key written to: {MASTER_KEY_FILE}")\n\n\nif __name__ == "__main__":\n    main()\n'

FILES["app/main.py"] = 'import logging\nimport uuid\nfrom contextlib import asynccontextmanager\n\nfrom fastapi import Depends, FastAPI, HTTPException, Request, status\nfrom fastapi.responses import JSONResponse\nfrom sqlalchemy import text\nfrom sqlalchemy.exc import SQLAlchemyError\nfrom sqlalchemy.orm import Session\n\nfrom app.api.v1.router import api_router\nfrom app.core.config import settings\nfrom app.db.dependencies import get_db\n\n\nlogger = logging.getLogger(__name__)\n\n\ndef validate_runtime_settings() -> None:\n    if settings.jwt_algorithm != "HS256":\n        raise RuntimeError("Only HS256 JWT algorithm is supported")\n\n    if settings.app_env == "dev":\n        return\n\n    if settings.app_debug:\n        raise RuntimeError("APP_DEBUG must be false outside dev")\n\n    if settings.postgres_password in {"change_me", "change_me_dev_only"}:\n        raise RuntimeError("POSTGRES_PASSWORD must be changed outside dev")\n\n    if settings.jwt_secret_key.startswith("change_me"):\n        raise RuntimeError("JWT_SECRET_KEY must be changed outside dev")\n\n    if settings.api_key_pepper.startswith("change_me"):\n        raise RuntimeError("API_KEY_PEPPER must be changed outside dev")\n\n\n@asynccontextmanager\nasync def lifespan(app: FastAPI):\n    validate_runtime_settings()\n    yield\n\n\napp = FastAPI(\n    title=settings.app_name,\n    debug=settings.app_debug,\n    docs_url="/docs" if settings.docs_enabled else None,\n    redoc_url="/redoc" if settings.docs_enabled else None,\n    openapi_url="/openapi.json" if settings.docs_enabled else None,\n    lifespan=lifespan,\n)\n\napp.include_router(api_router, prefix=settings.api_v1_prefix)\n\n\n@app.middleware("http")\nasync def request_id_middleware(request: Request, call_next):\n    request_id = request.headers.get("x-request-id") or str(uuid.uuid4())\n    request.state.request_id = request_id\n\n    response = await call_next(request)\n    response.headers["X-Request-ID"] = request_id\n\n    return response\n\n\n@app.exception_handler(SQLAlchemyError)\nasync def sqlalchemy_exception_handler(request: Request, exc: SQLAlchemyError):\n    request_id = getattr(request.state, "request_id", None)\n    logger.exception("Database error", extra={"request_id": request_id})\n\n    return JSONResponse(\n        status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\n        content={"detail": "Database is unavailable", "request_id": request_id},\n    )\n\n\n@app.exception_handler(Exception)\nasync def unhandled_exception_handler(request: Request, exc: Exception):\n    request_id = getattr(request.state, "request_id", None)\n    logger.exception("Unhandled application error", extra={"request_id": request_id})\n\n    return JSONResponse(\n        status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\n        content={"detail": "Internal server error", "request_id": request_id},\n    )\n\n\n@app.get("/health", include_in_schema=False)\n@app.get(f"{settings.api_v1_prefix}/health")\ndef health_check() -> dict[str, str]:\n    return {\n        "status": "ok",\n        "service": settings.app_name,\n        "api_prefix": settings.api_v1_prefix,\n    }\n\n\n@app.get(f"{settings.api_v1_prefix}/health/db")\ndef database_health_check(db: Session = Depends(get_db)) -> dict[str, str]:\n    try:\n        db.execute(text("SELECT 1"))\n    except SQLAlchemyError:\n        raise HTTPException(\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\n            detail="Database is unavailable",\n        )\n\n    return {"status": "ok", "database": "postgresql"}\n'

FILES["nginx/nginx.conf"] = 'events {\n    worker_connections 1024;\n}\n\nhttp {\n    include /etc/nginx/mime.types;\n    default_type application/octet-stream;\n    server_tokens off;\n\n    log_format main \'$remote_addr - $remote_user [$time_local] "$request" \'\n                    \'$status $body_bytes_sent "$http_referer" \'\n                    \'"$http_user_agent" "$http_x_forwarded_for" \'\n                    \'request_id="$request_id"\';\n\n    access_log /var/log/nginx/access.log main;\n    error_log /var/log/nginx/error.log warn;\n\n    sendfile on;\n    keepalive_timeout 65;\n    client_max_body_size 1m;\n\n    limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;\n    limit_req_zone $binary_remote_addr zone=login_limit:10m rate=5r/m;\n\n    upstream fastapi_backend {\n        server api:8000;\n        keepalive 32;\n    }\n\n    server {\n        listen 80;\n        server_name _;\n\n        location = /health {\n            access_log off;\n            proxy_pass http://fastapi_backend/health;\n            proxy_set_header Host $host;\n            proxy_set_header X-Real-IP $remote_addr;\n            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n            proxy_set_header X-Forwarded-Proto http;\n            proxy_set_header X-Request-ID $request_id;\n        }\n\n        location / {\n            return 301 https://$host:8443$request_uri;\n        }\n    }\n\n    server {\n        listen 443 ssl;\n        server_name _;\n\n        ssl_certificate /etc/nginx/certs/nginx.crt;\n        ssl_certificate_key /etc/nginx/certs/nginx.key;\n        ssl_protocols TLSv1.2 TLSv1.3;\n        ssl_prefer_server_ciphers off;\n\n        add_header X-Content-Type-Options "nosniff" always;\n        add_header X-Frame-Options "DENY" always;\n        add_header Referrer-Policy "no-referrer" always;\n        add_header Permissions-Policy "geolocation=(), microphone=(), camera=()" always;\n        add_header X-Request-ID "$request_id" always;\n\n        location = /health {\n            access_log off;\n            proxy_pass http://fastapi_backend/health;\n            proxy_set_header Host $host;\n            proxy_set_header X-Real-IP $remote_addr;\n            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n            proxy_set_header X-Forwarded-Proto https;\n            proxy_set_header X-Request-ID $request_id;\n        }\n\n        location = /api/v1/auth/login {\n            limit_req zone=login_limit burst=5 nodelay;\n            proxy_pass http://fastapi_backend;\n            proxy_http_version 1.1;\n            proxy_set_header Connection "";\n            proxy_set_header Host $host;\n            proxy_set_header X-Real-IP $remote_addr;\n            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n            proxy_set_header X-Forwarded-Proto https;\n            proxy_set_header X-Request-ID $request_id;\n            proxy_connect_timeout 5s;\n            proxy_send_timeout 30s;\n            proxy_read_timeout 30s;\n        }\n\n        location / {\n            limit_req zone=api_limit burst=20 nodelay;\n            proxy_pass http://fastapi_backend;\n            proxy_http_version 1.1;\n            proxy_set_header Connection "";\n            proxy_set_header Host $host;\n            proxy_set_header X-Real-IP $remote_addr;\n            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n            proxy_set_header X-Forwarded-Proto https;\n            proxy_set_header X-Request-ID $request_id;\n            proxy_connect_timeout 5s;\n            proxy_send_timeout 30s;\n            proxy_read_timeout 30s;\n        }\n    }\n}\n'

FILES["app/models/identity.py"] = 'import uuid\nfrom datetime import datetime\nfrom enum import StrEnum\n\nfrom sqlalchemy import CheckConstraint, DateTime, ForeignKey, Index, String, Text, func\nfrom sqlalchemy.dialects.postgresql import UUID\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom app.db.base import Base\n\n\nclass PrincipalType(StrEnum):\n    USER = "user"\n    SERVICE_ACCOUNT = "service_account"\n\n\nclass Principal(Base):\n    __tablename__ = "principals"\n\n    id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        primary_key=True,\n        default=uuid.uuid4,\n    )\n    principal_type: Mapped[str] = mapped_column(String(32), nullable=False)\n    display_name: Mapped[str] = mapped_column(String(255), nullable=False)\n    is_active: Mapped[bool] = mapped_column(default=True, nullable=False)\n    created_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        server_default=func.now(),\n        nullable=False,\n    )\n    disabled_at: Mapped[datetime | None] = mapped_column(\n        DateTime(timezone=True),\n        nullable=True,\n    )\n\n    __table_args__ = (\n        CheckConstraint(\n            "principal_type IN (\'user\', \'service_account\')",\n            name="ck_principals_principal_type_allowed",\n        ),\n    )\n\n\nclass User(Base):\n    __tablename__ = "users"\n\n    principal_id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("principals.id", ondelete="CASCADE"),\n        primary_key=True,\n    )\n    username: Mapped[str] = mapped_column(String(255), nullable=False)\n    password_hash: Mapped[str] = mapped_column(Text, nullable=False)\n    created_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        server_default=func.now(),\n        nullable=False,\n    )\n    last_login_at: Mapped[datetime | None] = mapped_column(\n        DateTime(timezone=True),\n        nullable=True,\n    )\n\n    __table_args__ = (\n        Index("users_username_lower_uq", func.lower(username), unique=True),\n    )\n\n\nclass ServiceAccount(Base):\n    __tablename__ = "service_accounts"\n\n    principal_id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("principals.id", ondelete="CASCADE"),\n        primary_key=True,\n    )\n    name: Mapped[str] = mapped_column(String(255), nullable=False)\n    api_key_prefix: Mapped[str] = mapped_column(String(64), nullable=False)\n    api_key_hash: Mapped[str] = mapped_column(Text, nullable=False)\n    owner_principal_id: Mapped[uuid.UUID | None] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("principals.id", ondelete="SET NULL"),\n        nullable=True,\n    )\n    expires_at: Mapped[datetime | None] = mapped_column(\n        DateTime(timezone=True),\n        nullable=True,\n    )\n    last_used_at: Mapped[datetime | None] = mapped_column(\n        DateTime(timezone=True),\n        nullable=True,\n    )\n    created_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        server_default=func.now(),\n        nullable=False,\n    )\n\n    __table_args__ = (\n        Index("service_accounts_name_lower_uq", func.lower(name), unique=True),\n        Index("service_accounts_api_key_prefix_uq", "api_key_prefix", unique=True),\n    )\n\n\nclass Role(Base):\n    __tablename__ = "roles"\n\n    id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        primary_key=True,\n        default=uuid.uuid4,\n    )\n    name: Mapped[str] = mapped_column(String(64), nullable=False)\n    description: Mapped[str | None] = mapped_column(Text, nullable=True)\n\n    __table_args__ = (\n        Index("roles_name_lower_uq", func.lower(name), unique=True),\n    )\n\n\nclass PrincipalRole(Base):\n    __tablename__ = "principal_roles"\n\n    principal_id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("principals.id", ondelete="CASCADE"),\n        primary_key=True,\n    )\n    role_id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("roles.id", ondelete="CASCADE"),\n        primary_key=True,\n    )\n    granted_by: Mapped[uuid.UUID | None] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("principals.id", ondelete="SET NULL"),\n        nullable=True,\n    )\n    granted_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        server_default=func.now(),\n        nullable=False,\n    )\n'

FILES["app/repositories/identity.py"] = 'import uuid\n\nfrom sqlalchemy import func, select\nfrom sqlalchemy.orm import Session\n\nfrom app.core.datetime import utc_now\nfrom app.models.identity import Principal, PrincipalRole, Role, ServiceAccount, User\n\n\ndef normalize_role_name(name: str) -> str:\n    normalized = name.strip().lower()\n    if not normalized:\n        raise ValueError("Role name cannot be empty")\n    return normalized\n\n\ndef get_principal_by_id(db: Session, principal_id: uuid.UUID) -> Principal | None:\n    return db.get(Principal, principal_id)\n\n\ndef get_user_by_username(db: Session, username: str) -> User | None:\n    normalized_username = username.strip().lower()\n    statement = select(User).where(func.lower(User.username) == normalized_username)\n    return db.scalar(statement)\n\n\ndef get_roles_for_principal(db: Session, principal_id: uuid.UUID) -> list[str]:\n    statement = (\n        select(Role.name)\n        .join(PrincipalRole, PrincipalRole.role_id == Role.id)\n        .where(PrincipalRole.principal_id == principal_id)\n    )\n    return list(db.scalars(statement).all())\n\n\ndef get_role_by_name(db: Session, name: str) -> Role | None:\n    normalized_name = normalize_role_name(name)\n    statement = select(Role).where(func.lower(Role.name) == normalized_name)\n    return db.scalar(statement)\n\n\ndef ensure_role(db: Session, name: str, description: str | None = None) -> Role:\n    normalized_name = normalize_role_name(name)\n\n    role = get_role_by_name(db, normalized_name)\n    if role is not None:\n        return role\n\n    role = Role(name=normalized_name, description=description)\n    db.add(role)\n    db.flush()\n    return role\n\n\ndef assign_role_to_principal(\n    db: Session,\n    principal_id: uuid.UUID,\n    role_id: uuid.UUID,\n    granted_by: uuid.UUID | None = None,\n) -> None:\n    existing = db.get(\n        PrincipalRole,\n        {"principal_id": principal_id, "role_id": role_id},\n    )\n    if existing is not None:\n        return\n\n    db.add(\n        PrincipalRole(\n            principal_id=principal_id,\n            role_id=role_id,\n            granted_by=granted_by,\n        )\n    )\n\n\ndef get_service_account_by_api_key_prefix(\n    db: Session,\n    api_key_prefix: str,\n) -> ServiceAccount | None:\n    statement = select(ServiceAccount).where(\n        ServiceAccount.api_key_prefix == api_key_prefix\n    )\n    return db.scalar(statement)\n\n\ndef update_service_account_last_used(\n    db: Session,\n    service_account: ServiceAccount,\n) -> None:\n    service_account.last_used_at = utc_now()\n    db.add(service_account)\n'

FILES["app/schemas/auth.py"] = 'import uuid\n\nfrom pydantic import BaseModel, Field, field_validator\n\n\nclass LoginRequest(BaseModel):\n    username: str = Field(min_length=3, max_length=255)\n    password: str = Field(min_length=1, max_length=1024)\n\n    @field_validator("username")\n    @classmethod\n    def normalize_username(cls, value: str) -> str:\n        return value.strip().lower()\n\n\nclass TokenResponse(BaseModel):\n    access_token: str\n    token_type: str = "bearer"\n    expires_in_minutes: int\n\n\nclass PrincipalResponse(BaseModel):\n    id: uuid.UUID\n    principal_type: str\n    display_name: str\n    roles: list[str]\n'

FILES["scripts/create_admin.py"] = 'import argparse\nimport getpass\nimport sys\n\nfrom sqlalchemy import func, select\n\nfrom app.core.security import hash_password\nfrom app.db.session import SessionLocal\nfrom app.models.identity import Principal, PrincipalRole, PrincipalType, Role, User\n\n\nDEFAULT_ROLES = {\n    "admin": "System administrator",\n    "developer": "Developer user",\n    "auditor": "Audit log reader",\n    "service": "Service account role",\n}\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description="Create initial admin user")\n    parser.add_argument("--username", required=True)\n    parser.add_argument("--password", required=False)\n    args = parser.parse_args()\n\n    username = args.username.strip().lower()\n    if not username:\n        print("Username cannot be empty", file=sys.stderr)\n        sys.exit(1)\n\n    password = args.password\n    if password is None:\n        password = getpass.getpass("Admin password: ")\n        password_confirm = getpass.getpass("Confirm password: ")\n        if password != password_confirm:\n            print("Passwords do not match", file=sys.stderr)\n            sys.exit(1)\n\n    if len(password) < 8:\n        print("Password must be at least 8 characters", file=sys.stderr)\n        sys.exit(1)\n\n    with SessionLocal() as db:\n        try:\n            existing_user = db.scalar(\n                select(User).where(func.lower(User.username) == username)\n            )\n            if existing_user is not None:\n                print(f"User \'{username}\' already exists", file=sys.stderr)\n                sys.exit(1)\n\n            roles: dict[str, Role] = {}\n            for role_name, description in DEFAULT_ROLES.items():\n                normalized_role_name = role_name.strip().lower()\n                role = db.scalar(\n                    select(Role).where(func.lower(Role.name) == normalized_role_name)\n                )\n                if role is None:\n                    role = Role(name=normalized_role_name, description=description)\n                    db.add(role)\n                    db.flush()\n                roles[normalized_role_name] = role\n\n            principal = Principal(\n                principal_type=PrincipalType.USER.value,\n                display_name=username,\n            )\n            db.add(principal)\n            db.flush()\n\n            user = User(\n                principal_id=principal.id,\n                username=username,\n                password_hash=hash_password(password),\n            )\n            db.add(user)\n            db.add(\n                PrincipalRole(\n                    principal_id=principal.id,\n                    role_id=roles["admin"].id,\n                    granted_by=None,\n                )\n            )\n            db.commit()\n        except Exception:\n            db.rollback()\n            raise\n\n    print(f"Admin user \'{username}\' created successfully")\n\n\nif __name__ == "__main__":\n    main()\n'

FILES["app/models/secrets.py"] = 'import uuid\nfrom datetime import datetime\n\nfrom sqlalchemy import (\n    Boolean,\n    CheckConstraint,\n    DateTime,\n    ForeignKey,\n    Index,\n    Integer,\n    String,\n    Text,\n    UniqueConstraint,\n    func,\n)\nfrom sqlalchemy.dialects.postgresql import UUID\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom app.db.base import Base\n\n\nclass Secret(Base):\n    __tablename__ = "secrets"\n\n    id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        primary_key=True,\n        default=uuid.uuid4,\n    )\n    path: Mapped[str] = mapped_column(String(512), nullable=False)\n    description: Mapped[str | None] = mapped_column(Text, nullable=True)\n    owner_principal_id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("principals.id", ondelete="RESTRICT"),\n        nullable=False,\n    )\n    current_version: Mapped[int] = mapped_column(\n        Integer,\n        nullable=False,\n        default=1,\n    )\n    is_deleted: Mapped[bool] = mapped_column(\n        Boolean,\n        nullable=False,\n        default=False,\n    )\n    created_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        server_default=func.now(),\n        nullable=False,\n    )\n    updated_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        server_default=func.now(),\n        onupdate=func.now(),\n        nullable=False,\n    )\n\n    __table_args__ = (\n        CheckConstraint(\n            "current_version >= 1",\n            name="ck_secrets_current_version_positive",\n        ),\n        Index(\n            "uq_secrets_path_active",\n            "path",\n            unique=True,\n            postgresql_where=is_deleted.is_(False),\n        ),\n        Index("ix_secrets_path", "path"),\n        Index("ix_secrets_owner_principal_id", "owner_principal_id"),\n    )\n\n\nclass SecretVersion(Base):\n    __tablename__ = "secret_versions"\n\n    id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        primary_key=True,\n        default=uuid.uuid4,\n    )\n    secret_id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("secrets.id", ondelete="CASCADE"),\n        nullable=False,\n    )\n    version: Mapped[int] = mapped_column(Integer, nullable=False)\n    ciphertext: Mapped[str] = mapped_column(Text, nullable=False)\n    key_version: Mapped[str] = mapped_column(String(64), nullable=False)\n    created_by: Mapped[uuid.UUID | None] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("principals.id", ondelete="SET NULL"),\n        nullable=True,\n    )\n    created_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        server_default=func.now(),\n        nullable=False,\n    )\n    expires_at: Mapped[datetime | None] = mapped_column(\n        DateTime(timezone=True),\n        nullable=True,\n    )\n\n    __table_args__ = (\n        CheckConstraint(\n            "version >= 1",\n            name="ck_secret_versions_version_positive",\n        ),\n        UniqueConstraint(\n            "secret_id",\n            "version",\n            name="uq_secret_versions_secret_id_version",\n        ),\n        Index("ix_secret_versions_secret_id", "secret_id"),\n    )\n\n\nclass AccessPolicy(Base):\n    __tablename__ = "access_policies"\n\n    id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        primary_key=True,\n        default=uuid.uuid4,\n    )\n    principal_id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("principals.id", ondelete="CASCADE"),\n        nullable=False,\n    )\n    secret_id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("secrets.id", ondelete="CASCADE"),\n        nullable=False,\n    )\n    capability: Mapped[str] = mapped_column(String(32), nullable=False)\n    created_by: Mapped[uuid.UUID | None] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("principals.id", ondelete="SET NULL"),\n        nullable=True,\n    )\n    created_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        server_default=func.now(),\n        nullable=False,\n    )\n\n    __table_args__ = (\n        CheckConstraint(\n            "capability IN (\'read\', \'update\', \'delete\', \'rotate\', \'manage_policy\')",\n            name="ck_access_policies_capability_allowed",\n        ),\n        UniqueConstraint(\n            "principal_id",\n            "secret_id",\n            "capability",\n            name="uq_access_policies_principal_secret_capability",\n        ),\n        Index("ix_access_policies_principal_id", "principal_id"),\n        Index("ix_access_policies_secret_id", "secret_id"),\n    )\n\n\nclass AuditLog(Base):\n    __tablename__ = "audit_logs"\n\n    id: Mapped[uuid.UUID] = mapped_column(\n        UUID(as_uuid=True),\n        primary_key=True,\n        default=uuid.uuid4,\n    )\n    actor_type: Mapped[str] = mapped_column(String(32), nullable=False)\n    actor_id: Mapped[uuid.UUID | None] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("principals.id", ondelete="SET NULL"),\n        nullable=True,\n    )\n    action: Mapped[str] = mapped_column(String(64), nullable=False)\n    status: Mapped[str] = mapped_column(String(32), nullable=False)\n    secret_id: Mapped[uuid.UUID | None] = mapped_column(\n        UUID(as_uuid=True),\n        ForeignKey("secrets.id", ondelete="SET NULL"),\n        nullable=True,\n    )\n    ip_address: Mapped[str | None] = mapped_column(String(64), nullable=True)\n    user_agent: Mapped[str | None] = mapped_column(Text, nullable=True)\n    request_id: Mapped[str | None] = mapped_column(String(128), nullable=True)\n    created_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        server_default=func.now(),\n        nullable=False,\n    )\n\n    __table_args__ = (\n        CheckConstraint(\n            "actor_type IN (\'user\', \'service_account\', \'system\', \'anonymous\')",\n            name="ck_audit_logs_actor_type_allowed",\n        ),\n        CheckConstraint(\n            "status IN (\'success\', \'denied\', \'failed\')",\n            name="ck_audit_logs_status_allowed",\n        ),\n        Index("ix_audit_logs_actor_id", "actor_id"),\n        Index("ix_audit_logs_secret_id", "secret_id"),\n        Index("ix_audit_logs_action", "action"),\n        Index("ix_audit_logs_created_at", "created_at"),\n    )\n'

FILES["app/schemas/secret.py"] = 'import uuid\nfrom datetime import datetime\nfrom typing import Annotated, Literal\n\nfrom pydantic import BaseModel, Field, field_validator\n\nfrom app.core.datetime import ensure_aware_utc\n\nSecretPath = Annotated[\n    str,\n    Field(\n        min_length=3,\n        max_length=512,\n        pattern=r"^[a-zA-Z0-9._/\\-]+$",\n    ),\n]\n\nCapability = Literal["read", "update", "delete", "rotate", "manage_policy"]\n\n\nclass SecretCreateRequest(BaseModel):\n    path: SecretPath\n    value: str = Field(min_length=1, max_length=10000)\n    description: str | None = Field(default=None, max_length=2000)\n    expires_at: datetime | None = None\n\n    @field_validator("expires_at")\n    @classmethod\n    def validate_expires_at(cls, value: datetime | None) -> datetime | None:\n        return ensure_aware_utc(value)\n\n\nclass SecretRotateRequest(BaseModel):\n    value: str = Field(min_length=1, max_length=10000)\n    expires_at: datetime | None = None\n\n    @field_validator("expires_at")\n    @classmethod\n    def validate_expires_at(cls, value: datetime | None) -> datetime | None:\n        return ensure_aware_utc(value)\n\n\nclass SecretMetadataResponse(BaseModel):\n    id: uuid.UUID\n    path: str\n    description: str | None\n    owner_principal_id: uuid.UUID\n    current_version: int\n    created_at: datetime\n    updated_at: datetime\n\n\nclass SecretValueResponse(BaseModel):\n    id: uuid.UUID\n    path: str\n    description: str | None\n    current_version: int\n    value: str\n    expires_at: datetime | None\n\n\nclass AccessPolicyCreateRequest(BaseModel):\n    secret_path: SecretPath\n    principal_id: uuid.UUID\n    capability: Capability\n\n\nclass AccessPolicyResponse(BaseModel):\n    id: uuid.UUID\n    principal_id: uuid.UUID\n    secret_id: uuid.UUID\n    capability: str\n    created_by: uuid.UUID | None\n    created_at: datetime\n'

FILES["app/core/security.py"] = 'import hashlib\nimport hmac\nimport re\nimport secrets\nimport uuid\nfrom datetime import datetime, timedelta, timezone\nfrom typing import Any\n\nimport jwt\nfrom jwt import InvalidTokenError\nfrom pwdlib import PasswordHash\n\nfrom app.core.config import settings\n\n\npassword_hash = PasswordHash.recommended()\nAPI_KEY_PREFIX_RE = re.compile(r"^smsk_live_[a-f0-9]{16}$")\n\n\ndef hash_password(password: str) -> str:\n    return password_hash.hash(password)\n\n\ndef verify_password(plain_password: str, hashed_password: str) -> bool:\n    return password_hash.verify(plain_password, hashed_password)\n\n\ndef create_access_token(\n    principal_id: uuid.UUID,\n    principal_type: str,\n) -> str:\n    now = datetime.now(timezone.utc)\n    expires_at = now + timedelta(minutes=settings.access_token_expire_minutes)\n\n    payload: dict[str, Any] = {\n        "sub": str(principal_id),\n        "type": principal_type,\n        "iat": int(now.timestamp()),\n        "exp": int(expires_at.timestamp()),\n        "iss": settings.app_name,\n    }\n\n    return jwt.encode(\n        payload,\n        settings.jwt_secret_key,\n        algorithm=settings.jwt_algorithm,\n    )\n\n\ndef decode_access_token(token: str) -> dict[str, Any] | None:\n    try:\n        return jwt.decode(\n            token,\n            settings.jwt_secret_key,\n            algorithms=[settings.jwt_algorithm],\n            issuer=settings.app_name,\n        )\n    except InvalidTokenError:\n        return None\n\n\ndef generate_api_key() -> tuple[str, str]:\n    public_part = secrets.token_hex(8)\n    secret_part = secrets.token_urlsafe(32)\n    prefix = f"smsk_live_{public_part}"\n    raw_api_key = f"{prefix}.{secret_part}"\n    return raw_api_key, prefix\n\n\ndef get_api_key_prefix(api_key: str) -> str | None:\n    prefix, separator, secret_part = api_key.partition(".")\n\n    if separator != "." or not secret_part:\n        return None\n\n    if API_KEY_PREFIX_RE.fullmatch(prefix) is None:\n        return None\n\n    return prefix\n\n\ndef hash_api_key(api_key: str) -> str:\n    return hmac.new(\n        settings.api_key_pepper.encode("utf-8"),\n        api_key.encode("utf-8"),\n        hashlib.sha256,\n    ).hexdigest()\n\n\ndef verify_api_key(api_key: str, expected_hash: str) -> bool:\n    actual_hash = hash_api_key(api_key)\n    return hmac.compare_digest(actual_hash, expected_hash)\n'

FILES["app/api/v1/dependencies.py"] = 'import uuid\nfrom collections.abc import Callable\nfrom typing import Annotated\n\nfrom fastapi import Depends, Header, HTTPException, status\nfrom sqlalchemy.orm import Session\n\nfrom app.core.security import decode_access_token\nfrom app.db.dependencies import get_db\nfrom app.models.identity import PrincipalType\nfrom app.services.auth_service import (\n    AuthenticatedPrincipal,\n    authenticate_api_key,\n    build_authenticated_principal_from_jwt,\n)\n\n\ndef _unauthorized(detail: str) -> HTTPException:\n    return HTTPException(\n        status_code=status.HTTP_401_UNAUTHORIZED,\n        detail=detail,\n        headers={"WWW-Authenticate": "Bearer"},\n    )\n\n\ndef get_current_principal(\n    db: Annotated[Session, Depends(get_db)],\n    authorization: Annotated[str | None, Header()] = None,\n    x_api_key: Annotated[str | None, Header(alias="X-API-Key")] = None,\n) -> AuthenticatedPrincipal:\n    if authorization is not None and x_api_key is not None:\n        raise HTTPException(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            detail="Use either Bearer token or X-API-Key, not both",\n        )\n\n    if authorization is not None:\n        scheme, _, token = authorization.partition(" ")\n        if scheme.lower() != "bearer" or not token.strip():\n            raise _unauthorized("Invalid authorization header")\n\n        payload = decode_access_token(token.strip())\n        if payload is None:\n            raise _unauthorized("Invalid access token")\n\n        try:\n            principal_id = uuid.UUID(payload["sub"])\n        except (KeyError, ValueError):\n            raise _unauthorized("Invalid access token payload")\n\n        token_type = payload.get("type")\n        allowed_types = {PrincipalType.USER.value, PrincipalType.SERVICE_ACCOUNT.value}\n        if token_type not in allowed_types:\n            raise _unauthorized("Invalid access token payload")\n\n        principal = build_authenticated_principal_from_jwt(db, principal_id)\n        if principal is None:\n            raise _unauthorized("Principal is inactive or does not exist")\n\n        if principal.principal_type != token_type:\n            raise _unauthorized("Invalid access token payload")\n\n        return principal\n\n    if x_api_key is not None:\n        principal = authenticate_api_key(db, x_api_key)\n        if principal is None:\n            raise HTTPException(\n                status_code=status.HTTP_401_UNAUTHORIZED,\n                detail="Invalid API key",\n            )\n        return principal\n\n    raise _unauthorized("Authentication required")\n\n\ndef require_roles(\n    *allowed_roles: str,\n) -> Callable[[AuthenticatedPrincipal], AuthenticatedPrincipal]:\n    normalized_allowed_roles = {role.strip().lower() for role in allowed_roles}\n\n    def dependency(\n        current_principal: Annotated[\n            AuthenticatedPrincipal,\n            Depends(get_current_principal),\n        ],\n    ) -> AuthenticatedPrincipal:\n        if not set(current_principal.roles).intersection(normalized_allowed_roles):\n            raise HTTPException(\n                status_code=status.HTTP_403_FORBIDDEN,\n                detail="Insufficient permissions",\n            )\n        return current_principal\n\n    return dependency\n'

FILES["app/api/v1/auth.py"] = 'from typing import Annotated\n\nfrom fastapi import APIRouter, Depends, HTTPException, status\nfrom sqlalchemy.orm import Session\n\nfrom app.api.v1.dependencies import get_current_principal\nfrom app.core.config import settings\nfrom app.core.security import create_access_token\nfrom app.db.dependencies import get_db\nfrom app.schemas.auth import LoginRequest, PrincipalResponse, TokenResponse\nfrom app.services.auth_service import AuthenticatedPrincipal, authenticate_user\n\n\nrouter = APIRouter(prefix="/auth", tags=["auth"])\n\n\n@router.post("/login", response_model=TokenResponse)\ndef login(\n    payload: LoginRequest,\n    db: Annotated[Session, Depends(get_db)],\n) -> TokenResponse:\n    principal = authenticate_user(\n        db=db,\n        username=payload.username,\n        password=payload.password,\n    )\n\n    if principal is None:\n        raise HTTPException(\n            status_code=status.HTTP_401_UNAUTHORIZED,\n            detail="Invalid username or password",\n        )\n\n    access_token = create_access_token(\n        principal_id=principal.id,\n        principal_type=principal.principal_type,\n    )\n\n    return TokenResponse(\n        access_token=access_token,\n        expires_in_minutes=settings.access_token_expire_minutes,\n    )\n\n\n@router.get("/me", response_model=PrincipalResponse)\ndef get_me(\n    current_principal: Annotated[\n        AuthenticatedPrincipal,\n        Depends(get_current_principal),\n    ],\n) -> PrincipalResponse:\n    return PrincipalResponse(\n        id=current_principal.id,\n        principal_type=current_principal.principal_type,\n        display_name=current_principal.display_name,\n        roles=current_principal.roles,\n    )\n'

FILES["app/services/auth_service.py"] = 'import uuid\nfrom dataclasses import dataclass\n\nfrom sqlalchemy.orm import Session\n\nfrom app.core.datetime import utc_now\nfrom app.core.security import get_api_key_prefix, verify_api_key, verify_password\nfrom app.models.identity import Principal\nfrom app.repositories.identity import (\n    get_principal_by_id,\n    get_roles_for_principal,\n    get_service_account_by_api_key_prefix,\n    get_user_by_username,\n    update_service_account_last_used,\n)\n\n\n@dataclass(frozen=True)\nclass AuthenticatedPrincipal:\n    id: uuid.UUID\n    principal_type: str\n    display_name: str\n    roles: list[str]\n\n\ndef authenticate_user(\n    db: Session,\n    username: str,\n    password: str,\n) -> AuthenticatedPrincipal | None:\n    user = get_user_by_username(db, username)\n    if user is None:\n        return None\n\n    principal = get_principal_by_id(db, user.principal_id)\n    if principal is None or not principal.is_active:\n        return None\n\n    if not verify_password(password, user.password_hash):\n        return None\n\n    user.last_login_at = utc_now()\n    db.add(user)\n    db.commit()\n\n    roles = get_roles_for_principal(db, principal.id)\n    return AuthenticatedPrincipal(\n        id=principal.id,\n        principal_type=principal.principal_type,\n        display_name=principal.display_name,\n        roles=roles,\n    )\n\n\ndef authenticate_api_key(db: Session, api_key: str) -> AuthenticatedPrincipal | None:\n    api_key_prefix = get_api_key_prefix(api_key)\n    if api_key_prefix is None:\n        return None\n\n    service_account = get_service_account_by_api_key_prefix(db, api_key_prefix)\n    if service_account is None:\n        return None\n\n    if service_account.expires_at is not None and service_account.expires_at <= utc_now():\n        return None\n\n    if not verify_api_key(api_key, service_account.api_key_hash):\n        return None\n\n    principal = get_principal_by_id(db, service_account.principal_id)\n    if principal is None or not principal.is_active:\n        return None\n\n    update_service_account_last_used(db, service_account)\n    db.commit()\n\n    roles = get_roles_for_principal(db, principal.id)\n    return AuthenticatedPrincipal(\n        id=principal.id,\n        principal_type=principal.principal_type,\n        display_name=principal.display_name,\n        roles=roles,\n    )\n\n\ndef build_authenticated_principal_from_jwt(\n    db: Session,\n    principal_id: uuid.UUID,\n) -> AuthenticatedPrincipal | None:\n    principal: Principal | None = get_principal_by_id(db, principal_id)\n    if principal is None or not principal.is_active:\n        return None\n\n    roles = get_roles_for_principal(db, principal.id)\n    return AuthenticatedPrincipal(\n        id=principal.id,\n        principal_type=principal.principal_type,\n        display_name=principal.display_name,\n        roles=roles,\n    )\n'

FILES["app/schemas/service_account.py"] = 'import uuid\nfrom datetime import datetime\n\nfrom pydantic import BaseModel, Field, field_validator\n\nfrom app.core.datetime import ensure_aware_utc\n\n\nclass ServiceAccountCreateRequest(BaseModel):\n    name: str = Field(min_length=3, max_length=255)\n    expires_at: datetime | None = None\n\n    @field_validator("name")\n    @classmethod\n    def normalize_name(cls, value: str) -> str:\n        normalized = value.strip()\n        if not normalized:\n            raise ValueError("Service account name cannot be empty")\n        return normalized\n\n    @field_validator("expires_at")\n    @classmethod\n    def validate_expires_at(cls, value: datetime | None) -> datetime | None:\n        return ensure_aware_utc(value)\n\n\nclass ServiceAccountCreateResponse(BaseModel):\n    principal_id: uuid.UUID\n    name: str\n    api_key: str\n    api_key_prefix: str\n    warning: str = "Save this API key now. It will not be shown again."\n'

FILES["app/services/audit_service.py"] = 'import uuid\n\nfrom fastapi import Request\nfrom sqlalchemy.orm import Session\n\nfrom app.models.secrets import AuditLog\nfrom app.services.auth_service import AuthenticatedPrincipal\n\n\ndef write_audit_event(\n    db: Session,\n    actor: AuthenticatedPrincipal | None,\n    action: str,\n    status: str,\n    secret_id: uuid.UUID | None = None,\n    request: Request | None = None,\n) -> None:\n    ip_address = None\n    user_agent = None\n    request_id = None\n\n    if request is not None:\n        ip_address = request.client.host if request.client is not None else None\n        user_agent = request.headers.get("user-agent")\n        request_id = getattr(request.state, "request_id", None)\n        if request_id is None:\n            request_id = request.headers.get("x-request-id")\n\n    db.add(\n        AuditLog(\n            actor_type=actor.principal_type if actor is not None else "anonymous",\n            actor_id=actor.id if actor is not None else None,\n            action=action,\n            status=status,\n            secret_id=secret_id,\n            ip_address=ip_address,\n            user_agent=user_agent,\n            request_id=request_id,\n        )\n    )\n'

FILES["app/services/service_account_service.py"] = 'from datetime import datetime\n\nfrom fastapi import Request\nfrom sqlalchemy.exc import IntegrityError\nfrom sqlalchemy.orm import Session\n\nfrom app.core.audit_actions import AuditAction, AuditStatus\nfrom app.core.datetime import ensure_aware_utc\nfrom app.core.security import generate_api_key, hash_api_key\nfrom app.models.identity import Principal, PrincipalType, ServiceAccount\nfrom app.repositories.identity import assign_role_to_principal, ensure_role\nfrom app.services.audit_service import write_audit_event\nfrom app.services.auth_service import AuthenticatedPrincipal\n\n\nclass ServiceAccountAlreadyExistsError(Exception):\n    pass\n\n\ndef create_service_account(\n    db: Session,\n    name: str,\n    expires_at: datetime | None,\n    current_principal: AuthenticatedPrincipal,\n    request: Request | None = None,\n) -> tuple[ServiceAccount, str]:\n    normalized_name = name.strip()\n    expires_at = ensure_aware_utc(expires_at)\n\n    raw_api_key, api_key_prefix = generate_api_key()\n\n    principal = Principal(\n        principal_type=PrincipalType.SERVICE_ACCOUNT.value,\n        display_name=normalized_name,\n    )\n    db.add(principal)\n    db.flush()\n\n    service_account = ServiceAccount(\n        principal_id=principal.id,\n        name=normalized_name,\n        api_key_prefix=api_key_prefix,\n        api_key_hash=hash_api_key(raw_api_key),\n        owner_principal_id=current_principal.id,\n        expires_at=expires_at,\n    )\n    db.add(service_account)\n\n    service_role = ensure_role(\n        db,\n        name="service",\n        description="Service account role",\n    )\n    assign_role_to_principal(\n        db,\n        principal_id=principal.id,\n        role_id=service_role.id,\n        granted_by=current_principal.id,\n    )\n\n    write_audit_event(\n        db=db,\n        actor=current_principal,\n        action=AuditAction.SERVICE_ACCOUNT_CREATED,\n        status=AuditStatus.SUCCESS,\n        request=request,\n    )\n\n    try:\n        db.commit()\n    except IntegrityError as exc:\n        db.rollback()\n        raise ServiceAccountAlreadyExistsError from exc\n\n    db.refresh(service_account)\n    return service_account, raw_api_key\n'

FILES["app/api/v1/service_accounts.py"] = 'from typing import Annotated\n\nfrom fastapi import APIRouter, Depends, HTTPException, Request, status\nfrom sqlalchemy.orm import Session\n\nfrom app.api.v1.dependencies import require_roles\nfrom app.db.dependencies import get_db\nfrom app.schemas.service_account import (\n    ServiceAccountCreateRequest,\n    ServiceAccountCreateResponse,\n)\nfrom app.services.auth_service import AuthenticatedPrincipal\nfrom app.services.service_account_service import (\n    ServiceAccountAlreadyExistsError,\n    create_service_account,\n)\n\n\nrouter = APIRouter(prefix="/service-accounts", tags=["service accounts"])\n\n\n@router.post("", response_model=ServiceAccountCreateResponse)\ndef create_service_account_endpoint(\n    payload: ServiceAccountCreateRequest,\n    request: Request,\n    db: Annotated[Session, Depends(get_db)],\n    current_principal: Annotated[\n        AuthenticatedPrincipal,\n        Depends(require_roles("admin")),\n    ],\n) -> ServiceAccountCreateResponse:\n    try:\n        service_account, raw_api_key = create_service_account(\n            db=db,\n            name=payload.name,\n            expires_at=payload.expires_at,\n            current_principal=current_principal,\n            request=request,\n        )\n    except ServiceAccountAlreadyExistsError:\n        raise HTTPException(\n            status_code=status.HTTP_409_CONFLICT,\n            detail="Service account already exists or API key prefix collided",\n        )\n\n    return ServiceAccountCreateResponse(\n        principal_id=service_account.principal_id,\n        name=service_account.name,\n        api_key=raw_api_key,\n        api_key_prefix=service_account.api_key_prefix,\n    )\n'

FILES["app/repositories/audit.py"] = 'import uuid\nfrom datetime import datetime\n\nfrom sqlalchemy import select\nfrom sqlalchemy.orm import Session\n\nfrom app.models.secrets import AuditLog\n\n\ndef list_audit_logs(\n    db: Session,\n    limit: int = 100,\n    actor_id: uuid.UUID | None = None,\n    secret_id: uuid.UUID | None = None,\n    action: str | None = None,\n    status: str | None = None,\n    request_id: str | None = None,\n    created_from: datetime | None = None,\n    created_to: datetime | None = None,\n) -> list[AuditLog]:\n    statement = select(AuditLog)\n\n    if actor_id is not None:\n        statement = statement.where(AuditLog.actor_id == actor_id)\n    if secret_id is not None:\n        statement = statement.where(AuditLog.secret_id == secret_id)\n    if action is not None:\n        statement = statement.where(AuditLog.action == action)\n    if status is not None:\n        statement = statement.where(AuditLog.status == status)\n    if request_id is not None:\n        statement = statement.where(AuditLog.request_id == request_id)\n    if created_from is not None:\n        statement = statement.where(AuditLog.created_at >= created_from)\n    if created_to is not None:\n        statement = statement.where(AuditLog.created_at <= created_to)\n\n    statement = statement.order_by(AuditLog.created_at.desc()).limit(limit)\n    return list(db.scalars(statement).all())\n'

FILES["app/api/v1/audit.py"] = 'import uuid\nfrom datetime import datetime\nfrom typing import Annotated\n\nfrom fastapi import APIRouter, Depends, Query\nfrom sqlalchemy.orm import Session\n\nfrom app.api.v1.dependencies import require_roles\nfrom app.core.datetime import ensure_aware_utc\nfrom app.db.dependencies import get_db\nfrom app.repositories.audit import list_audit_logs\nfrom app.schemas.audit import AuditLogResponse\nfrom app.services.auth_service import AuthenticatedPrincipal\n\n\nrouter = APIRouter(prefix="/audit", tags=["audit"])\n\n\n@router.get("", response_model=list[AuditLogResponse])\ndef list_audit_logs_endpoint(\n    db: Annotated[Session, Depends(get_db)],\n    current_principal: Annotated[\n        AuthenticatedPrincipal,\n        Depends(require_roles("admin", "auditor")),\n    ],\n    limit: Annotated[int, Query(ge=1, le=500)] = 100,\n    actor_id: uuid.UUID | None = None,\n    secret_id: uuid.UUID | None = None,\n    action: str | None = None,\n    status: str | None = None,\n    request_id: str | None = None,\n    created_from: datetime | None = None,\n    created_to: datetime | None = None,\n) -> list[AuditLogResponse]:\n    audit_logs = list_audit_logs(\n        db=db,\n        limit=limit,\n        actor_id=actor_id,\n        secret_id=secret_id,\n        action=action,\n        status=status,\n        request_id=request_id,\n        created_from=ensure_aware_utc(created_from),\n        created_to=ensure_aware_utc(created_to),\n    )\n\n    return [\n        AuditLogResponse(\n            id=audit_log.id,\n            actor_type=audit_log.actor_type,\n            actor_id=audit_log.actor_id,\n            action=audit_log.action,\n            status=audit_log.status,\n            secret_id=audit_log.secret_id,\n            ip_address=audit_log.ip_address,\n            user_agent=audit_log.user_agent,\n            request_id=audit_log.request_id,\n            created_at=audit_log.created_at,\n        )\n        for audit_log in audit_logs\n    ]\n'

FILES["app/services/secret_service.py"] = 'from datetime import datetime\n\nfrom fastapi import Request\nfrom sqlalchemy.orm import Session\n\nfrom app.core.audit_actions import AuditAction, AuditStatus\nfrom app.core.config import settings\nfrom app.core.datetime import ensure_aware_utc, utc_now\nfrom app.core.encryption import DecryptionError, decrypt_secret_value, encrypt_secret_value\nfrom app.models.secrets import AccessPolicy, Secret, SecretVersion\nfrom app.repositories.identity import get_principal_by_id\nfrom app.repositories.secrets import (\n    create_access_policy,\n    get_current_secret_version,\n    get_next_secret_version_number,\n    get_secret_by_path,\n    has_secret_capability,\n)\nfrom app.services.audit_service import write_audit_event\nfrom app.services.auth_service import AuthenticatedPrincipal\n\n\nOWNER_CAPABILITIES = ["read", "update", "delete", "rotate", "manage_policy"]\n\n\nclass SecretAlreadyExistsError(Exception):\n    pass\n\n\nclass SecretNotFoundError(Exception):\n    pass\n\n\nclass SecretAccessDeniedError(Exception):\n    pass\n\n\nclass SecretExpiredError(Exception):\n    pass\n\n\nclass SecretDecryptionFailedError(Exception):\n    pass\n\n\nclass TargetPrincipalNotFoundError(Exception):\n    pass\n\n\ndef create_secret(\n    db: Session,\n    path: str,\n    value: str,\n    description: str | None,\n    expires_at: datetime | None,\n    current_principal: AuthenticatedPrincipal,\n    request: Request | None = None,\n) -> Secret:\n    expires_at = ensure_aware_utc(expires_at)\n\n    existing_secret = get_secret_by_path(db, path)\n    if existing_secret is not None:\n        write_audit_event(\n            db=db,\n            actor=current_principal,\n            action=AuditAction.SECRET_CREATED,\n            status=AuditStatus.DENIED,\n            request=request,\n        )\n        db.commit()\n        raise SecretAlreadyExistsError\n\n    secret = Secret(\n        path=path,\n        description=description,\n        owner_principal_id=current_principal.id,\n        current_version=1,\n    )\n    db.add(secret)\n    db.flush()\n\n    secret_version = SecretVersion(\n        secret_id=secret.id,\n        version=1,\n        ciphertext=encrypt_secret_value(value),\n        key_version=settings.encryption_key_version,\n        created_by=current_principal.id,\n        expires_at=expires_at,\n    )\n    db.add(secret_version)\n\n    for capability in OWNER_CAPABILITIES:\n        create_access_policy(\n            db=db,\n            principal_id=current_principal.id,\n            secret_id=secret.id,\n            capability=capability,\n            created_by=current_principal.id,\n        )\n\n    write_audit_event(\n        db=db,\n        actor=current_principal,\n        action=AuditAction.SECRET_CREATED,\n        status=AuditStatus.SUCCESS,\n        secret_id=secret.id,\n        request=request,\n    )\n\n    db.commit()\n    db.refresh(secret)\n    return secret\n\n\ndef read_secret_value(\n    db: Session,\n    path: str,\n    current_principal: AuthenticatedPrincipal,\n    request: Request | None = None,\n) -> tuple[Secret, SecretVersion, str]:\n    secret = get_secret_by_path(db, path)\n    if secret is None:\n        raise SecretNotFoundError\n\n    if not has_secret_capability(db, secret, current_principal.id, "read"):\n        write_audit_event(\n            db=db,\n            actor=current_principal,\n            action=AuditAction.SECRET_READ,\n            status=AuditStatus.DENIED,\n            secret_id=secret.id,\n            request=request,\n        )\n        db.commit()\n        raise SecretAccessDeniedError\n\n    secret_version = get_current_secret_version(db, secret)\n    if secret_version is None:\n        raise SecretNotFoundError\n\n    if secret_version.expires_at is not None and secret_version.expires_at <= utc_now():\n        write_audit_event(\n            db=db,\n            actor=current_principal,\n            action=AuditAction.SECRET_READ,\n            status=AuditStatus.DENIED,\n            secret_id=secret.id,\n            request=request,\n        )\n        db.commit()\n        raise SecretExpiredError\n\n    try:\n        plaintext = decrypt_secret_value(secret_version.ciphertext)\n    except DecryptionError as exc:\n        write_audit_event(\n            db=db,\n            actor=current_principal,\n            action=AuditAction.SECRET_READ,\n            status=AuditStatus.FAILED,\n            secret_id=secret.id,\n            request=request,\n        )\n        db.commit()\n        raise SecretDecryptionFailedError from exc\n\n    write_audit_event(\n        db=db,\n        actor=current_principal,\n        action=AuditAction.SECRET_READ,\n        status=AuditStatus.SUCCESS,\n        secret_id=secret.id,\n        request=request,\n    )\n    db.commit()\n\n    return secret, secret_version, plaintext\n\n\ndef rotate_secret_value(\n    db: Session,\n    path: str,\n    value: str,\n    expires_at: datetime | None,\n    current_principal: AuthenticatedPrincipal,\n    request: Request | None = None,\n) -> Secret:\n    expires_at = ensure_aware_utc(expires_at)\n\n    secret = get_secret_by_path(db, path)\n    if secret is None:\n        raise SecretNotFoundError\n\n    if not has_secret_capability(db, secret, current_principal.id, "rotate"):\n        write_audit_event(\n            db=db,\n            actor=current_principal,\n            action=AuditAction.SECRET_ROTATED,\n            status=AuditStatus.DENIED,\n            secret_id=secret.id,\n            request=request,\n        )\n        db.commit()\n        raise SecretAccessDeniedError\n\n    next_version = get_next_secret_version_number(db, secret.id)\n    secret_version = SecretVersion(\n        secret_id=secret.id,\n        version=next_version,\n        ciphertext=encrypt_secret_value(value),\n        key_version=settings.encryption_key_version,\n        created_by=current_principal.id,\n        expires_at=expires_at,\n    )\n\n    secret.current_version = next_version\n    secret.updated_at = utc_now()\n\n    db.add(secret_version)\n    db.add(secret)\n\n    write_audit_event(\n        db=db,\n        actor=current_principal,\n        action=AuditAction.SECRET_ROTATED,\n        status=AuditStatus.SUCCESS,\n        secret_id=secret.id,\n        request=request,\n    )\n\n    db.commit()\n    db.refresh(secret)\n    return secret\n\n\ndef delete_secret(\n    db: Session,\n    path: str,\n    current_principal: AuthenticatedPrincipal,\n    request: Request | None = None,\n) -> None:\n    secret = get_secret_by_path(db, path)\n    if secret is None:\n        raise SecretNotFoundError\n\n    if not has_secret_capability(db, secret, current_principal.id, "delete"):\n        write_audit_event(\n            db=db,\n            actor=current_principal,\n            action=AuditAction.SECRET_DELETED,\n            status=AuditStatus.DENIED,\n            secret_id=secret.id,\n            request=request,\n        )\n        db.commit()\n        raise SecretAccessDeniedError\n\n    secret.is_deleted = True\n    secret.updated_at = utc_now()\n    db.add(secret)\n\n    write_audit_event(\n        db=db,\n        actor=current_principal,\n        action=AuditAction.SECRET_DELETED,\n        status=AuditStatus.SUCCESS,\n        secret_id=secret.id,\n        request=request,\n    )\n    db.commit()\n\n\ndef grant_secret_access(\n    db: Session,\n    secret_path: str,\n    target_principal_id,\n    capability: str,\n    current_principal: AuthenticatedPrincipal,\n    request: Request | None = None,\n) -> AccessPolicy:\n    secret = get_secret_by_path(db, secret_path)\n    if secret is None:\n        raise SecretNotFoundError\n\n    can_manage_policy = (\n        "admin" in current_principal.roles\n        or has_secret_capability(db, secret, current_principal.id, "manage_policy")\n    )\n\n    if not can_manage_policy:\n        write_audit_event(\n            db=db,\n            actor=current_principal,\n            action=AuditAction.POLICY_CREATED,\n            status=AuditStatus.DENIED,\n            secret_id=secret.id,\n            request=request,\n        )\n        db.commit()\n        raise SecretAccessDeniedError\n\n    target_principal = get_principal_by_id(db, target_principal_id)\n    if target_principal is None or not target_principal.is_active:\n        raise TargetPrincipalNotFoundError\n\n    policy = create_access_policy(\n        db=db,\n        principal_id=target_principal_id,\n        secret_id=secret.id,\n        capability=capability,\n        created_by=current_principal.id,\n    )\n\n    write_audit_event(\n        db=db,\n        actor=current_principal,\n        action=AuditAction.POLICY_CREATED,\n        status=AuditStatus.SUCCESS,\n        secret_id=secret.id,\n        request=request,\n    )\n\n    db.commit()\n    db.refresh(policy)\n    return policy\n'

FILES["app/api/v1/secrets.py"] = 'from typing import Annotated\n\nfrom fastapi import APIRouter, Depends, HTTPException, Request, Response, status\nfrom sqlalchemy.orm import Session\n\nfrom app.api.v1.dependencies import get_current_principal, require_roles\nfrom app.db.dependencies import get_db\nfrom app.repositories.secrets import list_accessible_secrets\nfrom app.schemas.secret import (\n    SecretCreateRequest,\n    SecretMetadataResponse,\n    SecretRotateRequest,\n    SecretValueResponse,\n)\nfrom app.services.auth_service import AuthenticatedPrincipal\nfrom app.services.secret_service import (\n    SecretAccessDeniedError,\n    SecretAlreadyExistsError,\n    SecretDecryptionFailedError,\n    SecretExpiredError,\n    SecretNotFoundError,\n    create_secret,\n    delete_secret,\n    read_secret_value,\n    rotate_secret_value,\n)\n\n\nrouter = APIRouter(prefix="/secrets", tags=["secrets"])\n\n\ndef to_secret_metadata_response(secret) -> SecretMetadataResponse:\n    return SecretMetadataResponse(\n        id=secret.id,\n        path=secret.path,\n        description=secret.description,\n        owner_principal_id=secret.owner_principal_id,\n        current_version=secret.current_version,\n        created_at=secret.created_at,\n        updated_at=secret.updated_at,\n    )\n\n\n@router.post(\n    "",\n    response_model=SecretMetadataResponse,\n    status_code=status.HTTP_201_CREATED,\n)\ndef create_secret_endpoint(\n    payload: SecretCreateRequest,\n    request: Request,\n    db: Annotated[Session, Depends(get_db)],\n    current_principal: Annotated[\n        AuthenticatedPrincipal,\n        Depends(require_roles("admin", "developer")),\n    ],\n) -> SecretMetadataResponse:\n    try:\n        secret = create_secret(\n            db=db,\n            path=payload.path,\n            value=payload.value,\n            description=payload.description,\n            expires_at=payload.expires_at,\n            current_principal=current_principal,\n            request=request,\n        )\n    except SecretAlreadyExistsError:\n        raise HTTPException(\n            status_code=status.HTTP_409_CONFLICT,\n            detail="Secret already exists",\n        )\n\n    return to_secret_metadata_response(secret)\n\n\n@router.get("", response_model=list[SecretMetadataResponse])\ndef list_secrets_endpoint(\n    db: Annotated[Session, Depends(get_db)],\n    current_principal: Annotated[\n        AuthenticatedPrincipal,\n        Depends(get_current_principal),\n    ],\n) -> list[SecretMetadataResponse]:\n    can_see_all_metadata = bool(\n        {"admin", "auditor"}.intersection(current_principal.roles)\n    )\n    secrets = list_accessible_secrets(\n        db=db,\n        principal_id=current_principal.id,\n        can_see_all_metadata=can_see_all_metadata,\n    )\n    return [to_secret_metadata_response(secret) for secret in secrets]\n\n\n@router.post(\n    "/{secret_path:path}/versions",\n    response_model=SecretMetadataResponse,\n)\ndef rotate_secret_endpoint(\n    secret_path: str,\n    payload: SecretRotateRequest,\n    request: Request,\n    db: Annotated[Session, Depends(get_db)],\n    current_principal: Annotated[\n        AuthenticatedPrincipal,\n        Depends(get_current_principal),\n    ],\n) -> SecretMetadataResponse:\n    try:\n        secret = rotate_secret_value(\n            db=db,\n            path=secret_path,\n            value=payload.value,\n            expires_at=payload.expires_at,\n            current_principal=current_principal,\n            request=request,\n        )\n    except SecretNotFoundError:\n        raise HTTPException(\n            status_code=status.HTTP_404_NOT_FOUND,\n            detail="Secret not found",\n        )\n    except SecretAccessDeniedError:\n        raise HTTPException(\n            status_code=status.HTTP_403_FORBIDDEN,\n            detail="Insufficient secret permissions",\n        )\n\n    return to_secret_metadata_response(secret)\n\n\n@router.get("/{secret_path:path}", response_model=SecretValueResponse)\ndef read_secret_endpoint(\n    secret_path: str,\n    request: Request,\n    db: Annotated[Session, Depends(get_db)],\n    current_principal: Annotated[\n        AuthenticatedPrincipal,\n        Depends(get_current_principal),\n    ],\n) -> SecretValueResponse:\n    try:\n        secret, secret_version, plaintext = read_secret_value(\n            db=db,\n            path=secret_path,\n            current_principal=current_principal,\n            request=request,\n        )\n    except SecretNotFoundError:\n        raise HTTPException(\n            status_code=status.HTTP_404_NOT_FOUND,\n            detail="Secret not found",\n        )\n    except SecretAccessDeniedError:\n        raise HTTPException(\n            status_code=status.HTTP_403_FORBIDDEN,\n            detail="Insufficient secret permissions",\n        )\n    except SecretExpiredError:\n        raise HTTPException(\n            status_code=status.HTTP_410_GONE,\n            detail="Secret version has expired",\n        )\n    except SecretDecryptionFailedError:\n        raise HTTPException(\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\n            detail="Secret cannot be decrypted",\n        )\n\n    return SecretValueResponse(\n        id=secret.id,\n        path=secret.path,\n        description=secret.description,\n        current_version=secret.current_version,\n        value=plaintext,\n        expires_at=secret_version.expires_at,\n    )\n\n\n@router.delete(\n    "/{secret_path:path}",\n    status_code=status.HTTP_204_NO_CONTENT,\n)\ndef delete_secret_endpoint(\n    secret_path: str,\n    request: Request,\n    db: Annotated[Session, Depends(get_db)],\n    current_principal: Annotated[\n        AuthenticatedPrincipal,\n        Depends(get_current_principal),\n    ],\n) -> Response:\n    try:\n        delete_secret(\n            db=db,\n            path=secret_path,\n            current_principal=current_principal,\n            request=request,\n        )\n    except SecretNotFoundError:\n        raise HTTPException(\n            status_code=status.HTTP_404_NOT_FOUND,\n            detail="Secret not found",\n        )\n    except SecretAccessDeniedError:\n        raise HTTPException(\n            status_code=status.HTTP_403_FORBIDDEN,\n            detail="Insufficient secret permissions",\n        )\n\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\n'

