def backup_file(path: Path) -> None:
    if not path.exists():
        return
    backup_path = BACKUP_ROOT / path.relative_to(ROOT)
    backup_path.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(path, backup_path)


def write_file(relative_path: str, content: str) -> None:
    path = ROOT / relative_path
    backup_file(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8", newline="\n")
    print(f"wrote {relative_path}")


def patch_client() -> None:
    path = ROOT / "scripts/client.py"
    if not path.exists():
        return

    backup_file(path)
    text = path.read_text(encoding="utf-8")
    text = text.replace(
        'DEFAULT_BASE_URL = "http://127.0.0.1:8000"',
        'DEFAULT_BASE_URL = "https://127.0.0.1:8443"',
    )
    text = text.replace(
        'capabilities = ["read", "create", "update", "delete", "rotate", "manage_policy"]',
        'capabilities = ["read", "update", "delete", "rotate", "manage_policy"]',
    )
    path.write_text(text, encoding="utf-8", newline="\n")
    print("patched scripts/client.py")


def main() -> None:
    print(f"Project root: {ROOT}")
    print(f"Backup dir:   {BACKUP_ROOT}")
    BACKUP_ROOT.mkdir(parents=True, exist_ok=True)

    for relative_path, content in FILES.items():
        write_file(relative_path, content)

    patch_client()

    print("\nDone. Next commands:")
    print("  python -m compileall app scripts")
    print("  git diff")
    print("  docker compose build")
    print("  docker compose run --rm api alembic upgrade head")


if __name__ == "__main__":
    main()
